from funcy import memoize, cache, reraise
from funcy.calc import SkipMemoization
from functools import partial

for decorate in (memoize, memoize(), cache(60)):
    calls = []
    @decorate
    def f(*args, **kwargs):
        calls.append((args, kwargs))
        return len(calls)
    assert f(1, b=2, a=3) == f(1, a=3, b=2) == 1
    assert f(2) == 2
    memory = f.memory
    f.invalidate(1, a=3, b=2)
    f.invalidate(1, b=2, a=3)
    assert f(1, a=3, b=2) == 3
    assert f(2) == 2
    f.invalidate_all()
    assert f.memory is memory and memory == {}
    assert f(2) == 4
    assert f.skip is SkipMemoization

for decorate in (memoize, cache):
    kwargs = {'key_func': lambda value, ignored=None: value['id']}
    if decorate is cache:
        kwargs['timeout'] = 60
    calls = []
    @decorate(**kwargs)
    def f(value, ignored=None):
        calls.append(value)
        return len(calls)
    assert f({'id': 1}) == f({'id': 1}, ignored=True) == 1
    f.invalidate({'id': 1}, ignored=False)
    assert f({'id': 1}) == 2

for decorate in (memoize, cache(60)):
    @decorate
    def skipped(*args):
        raise skipped.skip(*args)
    assert skipped(42) == 42
    assert skipped() is None
    assert skipped.memory == {}

original = ValueError('original')
instance = RuntimeError('fixed')
seen = []
def transform(error):
    seen.append(error)
    return RuntimeError(str(error))
class Factory:
    def __call__(self, error):
        return RuntimeError(str(error))
for into in (RuntimeError, instance, transform, Factory(), partial(transform)):
    try:
        with reraise(ValueError, into):
            raise original
    except RuntimeError as error:
        assert error.__cause__ is original
        if into is RuntimeError:
            assert error.args == ()
        elif into is instance:
            assert error is instance
        else:
            assert str(error) == 'original'
    else:
        raise AssertionError('not raised')
assert seen == [original, original]

@reraise(ValueError, transform)
def decorated(error=None):
    if error:
        raise error
    return 42
assert decorated() == 42
for _ in range(2):
    try:
        decorated(original)
    except RuntimeError as error:
        assert error.__cause__ is original
try:
    decorated(KeyError('unmatched'))
except KeyError:
    pass
else:
    raise AssertionError('unmatched exception was intercepted')
print('Focused requirement checks passed')
